mapper.select:
SELECT c.*
FROM conversation c
WHERE c.user_a = #{userA}
  AND c.user_b = #{userB}
LIMIT 1

mapper.update:
UPDATE conversation
SET last_seq = last_seq + 1,
    updated_at = #{messageAt}
WHERE id = #{conversationId}
  AND status IN ('ACTIVE', 'WAITING_REPLY')

UPDATE conversation
SET created_by = #{senderId},
    status = #{status}
WHERE id = #{conversationId}
  AND last_seq = 0

mapper.select:
SELECT last_seq
FROM conversation
WHERE id = #{conversationId}

mapper.update:
UPDATE conversation
SET announcement = #{announcement},
    announcement_version = IFNULL(announcement_version, 0) + 1,
    updated_at = #{publishedAt}
WHERE id = #{conversationId}
